"""Installer must clear Hyprland's first-run autogenerated banner."""

from __future__ import annotations

import subprocess
import tempfile
import textwrap
import unittest
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
INSTALLER = ROOT / "scripts" / "install-debian-profile.sh"
REPAIR = ROOT / "scripts" / "repair-desktop-chrome.sh"


class AutogeneratedBannerTests(unittest.TestCase):
    def test_installer_defines_clear_helper(self) -> None:
        text = INSTALLER.read_text(encoding="utf-8")
        self.assertIn("clear_hyprland_autogenerated", text)
        self.assertIn("autogenerated", text)
        self.assertIn("disable_hyprland_logo", text)

    def test_repair_script_clears_autogenerated(self) -> None:
        text = REPAIR.read_text(encoding="utf-8")
        self.assertIn("autogenerated", text)
        self.assertIn("disable_hyprland_logo", text)

    def test_clear_sed_comments_out_flag(self) -> None:
        with tempfile.TemporaryDirectory() as temp:
            conf = Path(temp) / "hyprland.conf"
            conf.write_text(
                textwrap.dedent(
                    """\
                    # test
                    autogenerated = 1
                    source = ~/.config/hypr/aidycos.conf
                    exec-once = /usr/local/bin/jugoo
                    misc {
                    }
                    """
                ),
                encoding="utf-8",
            )
            # Same transform the installer/repair scripts apply.
            subprocess.run(
                [
                    "sed",
                    "-i",
                    "-E",
                    r"s/^[[:space:]]*autogenerated[[:space:]]*=[[:space:]]*1([[:space:]].*)?$/# autogenerated = 0  # AidyCOS: quita el aviso de config autogenerada/",
                    str(conf),
                ],
                check=True,
            )
            text = conf.read_text(encoding="utf-8")
            self.assertNotRegex(text, r"(?m)^[ \t]*autogenerated[ \t]*=[ \t]*1([ \t]|$)")
            self.assertIn("# autogenerated = 0", text)

    def test_repair_clears_live_conf(self) -> None:
        with tempfile.TemporaryDirectory() as temp:
            home = Path(temp)
            hypr = home / ".config" / "hypr"
            hypr.mkdir(parents=True)
            conf = hypr / "hyprland.conf"
            conf.write_text(
                "autogenerated = 1\nsource = ~/.config/hypr/aidycos.conf\n",
                encoding="utf-8",
            )
            # Extract only the autogenerated-clear block from repair and run it.
            script = textwrap.dedent(
                f"""
                set -euo pipefail
                HYPR_HOME="{hypr}"
                HYPR_CONF="{conf}"
                if [[ -f "${{HYPR_CONF}}" ]] && grep -qE '^[[:space:]]*autogenerated[[:space:]]*=[[:space:]]*1([[:space:]]|$)' "${{HYPR_CONF}}"; then
                  sed -i -E 's/^[[:space:]]*autogenerated[[:space:]]*=[[:space:]]*1([[:space:]].*)?$/# autogenerated = 0  # AidyCOS: quita el aviso de config autogenerada/' "${{HYPR_CONF}}"
                fi
                ! grep -qE '^[[:space:]]*autogenerated[[:space:]]*=[[:space:]]*1([[:space:]]|$)' "${{HYPR_CONF}}"
                grep -qE '^# autogenerated = 0' "${{HYPR_CONF}}"
                """
            )
            result = subprocess.run(
                ["bash", "-c", script],
                capture_output=True,
                text=True,
                check=False,
            )
            self.assertEqual(result.returncode, 0, result.stderr)
            self.assertIn("# autogenerated = 0", conf.read_text(encoding="utf-8"))


if __name__ == "__main__":
    unittest.main()
